import eslint from '@eslint/js';
import tseslint from 'typescript-eslint';
import obsidianmd from 'eslint-plugin-obsidianmd';

export default tseslint.config(
  {
    // Build output and dependencies are not source. main.js is generated by
    // esbuild and committed only so releases can ship it.
    ignores: ['main.js', 'node_modules/**', 'dist/**'],
  },
  eslint.configs.recommended,
  ...tseslint.configs.recommended,
  // Obsidian's official guideline rules. Its recommended config carries its own
  // file globs (TS, JS and package.json), so it is applied without narrowing.
  ...obsidianmd.configs.recommended,
  {
    // Several recommended rules are type-aware and need the TS program.
    files: ['**/*.ts'],
    languageOptions: {
      parserOptions: {
        projectService: true,
        tsconfigRootDir: import.meta.dirname,
      },
    },
  },
  {
    // The build and lint configs are plain ESM outside the TS program, so the
    // type-aware rules cannot run on them.
    files: ['**/*.{js,cjs,mjs}'],
    ...tseslint.configs.disableTypeChecked,
  },
  {
    // esbuild.config.mjs runs under Node at build time, never inside Obsidian.
    files: ['esbuild.config.mjs'],
    languageOptions: {
      globals: { process: 'readonly' },
    },
  },
  {
    // Sentence case is the Obsidian convention, but the rule cannot know this
    // plugin's vocabulary. Declaring it keeps product names, acronyms and the
    // literal frontmatter property names correctly cased instead of being
    // flattened to "ics url" or "english (title, date, context)".
    rules: {
      'obsidianmd/ui/sentence-case': [
        'warn',
        {
          brands: ['Memento', 'Obsidian', 'Google', 'Google Calendar', 'iCloud'],
          acronyms: ['ICS', 'JSON', 'URL', 'YAML', 'UID'],
          ignoreWords: [
            // Frontmatter property names quoted verbatim in the UI.
            'Title',
            'Date',
            'Context',
            'Título',
            'Fecha',
            'Contexto',
          ],
          ignoreRegex: [
            // The frontmatter-language options quote the literal property names
            // in each language. The rule tokenises on ASCII word characters, so
            // it cannot see "Título" as one word; sentence case does not apply
            // to these labels anyway.
            '^(English|Spanish) \\(',
          ],
        },
      ],
    },
  },
);
